// Node shim of @dynatrace-sdk/automation-utils. Params come from WF_PARAMS (JSON), predecessor
// results from the in-process store filled by run_task.mjs (globalThis.__wfResults).
export async function execution() {
  const params = JSON.parse(process.env.WF_PARAMS ?? "{}");
  const input = JSON.parse(process.env.WF_INPUT ?? "{}");
  return { id: "mock-execution", params, input, event: () => ({}) };
}
export async function result(taskName) {
  const store = globalThis.__wfResults ?? {};
  if (!(taskName in store)) throw new Error(`mock result(): task "${taskName}" has not run`);
  return store[taskName];
}
export const executionId = "mock-execution";
export const workflowId = "mock-workflow";
